  p={'http':f'http://{proxy}','https':f'http://{proxy}'}
  for attempt in range(2):
   try:
    r=requests.post('https://api.opengwas.io/api/gwasinfo/files/trial',json={'id':id_,'type':'vcf'},proxies=p,timeout=20)
    if r.status_code==200:
     return r.json(), proxy
    if r.status_code"'!=429:
     # print briefly
     pass
   except Exception:
    pass
   time.sleep(0.3)
 return None,None

def parse_val(v):
 try:return float(v)
 except:return None

out=open('"'scan_52_58_results.txt','w',buffering=1)
ids=[]
