  if afv is not None and af is not None and (abs(afv-af)<0.01 or abs((1-afv)-af)<0.01): score+=2
  matches.append(score)
  allrows.append((rs,score,es,sev,afv,f[2],f[3],f[4]))
 total=sum(matches) if matches else -1
